256	     * pre-tenure factors max out at level 3, so only tenure reaches level 4.
257	     */
258	    @Transient
259	    public int getMembershipLevel() {
260	        int level = 1;
261	        boolean hasEmail = this.email != null && !this.email.isEmpty();
262	        if (hasEmail) {
263	            level++;
264	        }
265	        boolean uniquelyNamed = Integer.valueOf(0).equals(this.namesakeCount);
266	        if (uniquelyNamed) {
267	            level++;
