340	
341	    public void addPet(Pet pet) {
342	        getPetsInternal().add(pet);
343	        pet.setOwner(this);
344	    }
345	
346	    /**
347	     * Return the Pet with the given name, or null if none found for this Owner.
348	     *
349	     * @param name to test
350	     * @return true if pet name is already in use
351	     */
352	    public Pet getPet(String name) {
353	        return getPet(name, false);
