17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.model.BusinessDayAdjuster;
33	import org.springframework.samples.petclinic.model.RegionResolver;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.audit.OwnerAuditLogger;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
43	import org.springframework.samples.petclinic.rest.validation.CityOwnerCapacityValidator;
44	import org.springframework.samples.petclinic.rest.validation.CustomerCodeGenerator;
45	import org.springframework.samples.petclinic.rest.validation.DailyRegistrationCapacityValidator;
46	import org.springframework.samples.petclinic.rest.validation.DisposableEmailDomainValidator;
47	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
48	import org.springframework.samples.petclinic.rest.validation.HouseholdDuplicateValidator;
49	import org.springframework.samples.petclinic.rest.validation.HouseholdKey;
50	import org.springframework.samples.petclinic.rest.validation.MembershipNumberGenerator;
51	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
52	import org.springframework.samples.petclinic.rest.validation.NamesakeCounter;
53	import org.springframework.samples.petclinic.rest.validation.PossibleDuplicateOwnerDetector;
54	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
55	import org.springframework.samples.petclinic.rest.validation.RegistrationDateValidator;
56	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
57	import org.springframework.samples.petclinic.service.ClinicService;
58	import org.springframework.security.access.prepost.PreAuthorize;
59	import org.springframework.web.bind.annotation.CrossOrigin;
60	import org.springframework.web.bind.annotation.RequestMapping;
61	import org.springframework.web.bind.annotation.RestController;
62	import org.springframework.web.util.UriComponentsBuilder;
63	
64	import jakarta.transaction.Transactional;
65	
66	/**
67	 * @author Vitaliy Fedoriv
68	 */
69	
70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    private final HouseholdDuplicateValidator householdDuplicateValidator;
84	
85	    private final PossibleDuplicateOwnerDetector possibleDuplicateOwnerDetector;
86	
87	    private final NamesakeCounter namesakeCounter;
88	
89	    private final CityOwnerCapacityValidator cityOwnerCapacityValidator;
90	
91	    private final DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator;
92	
93	    private final OwnerAuditLogger ownerAuditLogger;
94	
95	    public OwnerRestControllerV1(ClinicService clinicService,
96	                                 OwnerMapper ownerMapper,
97	                                 PetMapper petMapper,
98	                                 VisitMapper visitMapper,
99	                                 HouseholdDuplicateValidator householdDuplicateValidator,
100	                                 PossibleDuplicateOwnerDetector possibleDuplicateOwnerDetector,
101	                                 NamesakeCounter namesakeCounter,
102	                                 CityOwnerCapacityValidator cityOwnerCapacityValidator,
103	                                 DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator,
104	                                 OwnerAuditLogger ownerAuditLogger) {
105	        this.clinicService = clinicService;
106	        this.ownerMapper = ownerMapper;
107	        this.petMapper = petMapper;
108	        this.visitMapper = visitMapper;
109	        this.householdDuplicateValidator = householdDuplicateValidator;
110	        this.possibleDuplicateOwnerDetector = possibleDuplicateOwnerDetector;
111	        this.namesakeCounter = namesakeCounter;
112	        this.cityOwnerCapacityValidator = cityOwnerCapacityValidator;
113	        this.dailyRegistrationCapacityValidator = dailyRegistrationCapacityValidator;
114	        this.ownerAuditLogger = ownerAuditLogger;
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
120	        Collection<Owner> owners;
121	        if (lastName != null) {
122	            owners = this.clinicService.findOwnerByLastName(lastName);
123	        } else {
124	            owners = this.clinicService.findAllOwners();
125	        }
126	        if (owners.isEmpty()) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
135	        Owner owner = this.clinicService.findOwnerById(ownerId);
136	        if (owner == null) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
145	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
146	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
147	        HttpHeaders headers = new HttpHeaders();
148	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
149	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
150	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
151	        DisposableEmailDomainValidator.validate(owner.getEmail());
152	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
153	        RegistrationDateValidator.validateNotFuture(owner.getRegistrationDate());
154	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
155	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
156	        this.dailyRegistrationCapacityValidator.validateHasCapacity(owner.getRegistrationDate());
157	        owner.setHouseholdId(HouseholdKey.idFor(owner.getLastName(), owner.getPostcode()));
158	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
159	            // An owner sharing a household (same last name and postcode) is otherwise a household
160	            // duplicate. A declared member bypasses this block, and is not a suspected duplicate.
161	            this.householdDuplicateValidator.rejectIfHouseholdExists(owner);
162	            this.possibleDuplicateOwnerDetector.findPossibleDuplicateOf(owner)
163	                .ifPresent(owner::setPossibleDuplicateOf);
164	        }
165	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
166	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
167	        String region = RegionResolver.regionFor(owner.getPostcode(), owner.getCity());
168	        owner.setCustomerCode(CustomerCodeGenerator.generate(region, owner.getTelephone(), owner.getLastName()));
169	        this.clinicService.saveOwner(owner);
170	        owner.setMembershipNumber(MembershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
171	        this.ownerAuditLogger.logCreated(owner);
172	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
173	        headers.setLocation(UriComponentsBuilder.newInstance()
174	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
175	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
181	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
182	        if (currentOwner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        currentOwner.setAddress(ownerFieldsDto.getAddress());
186	        currentOwner.setCity(ownerFieldsDto.getCity());
187	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
188	        currentOwner.setLastName(ownerFieldsDto.getLastName());
189	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
190	        this.clinicService.saveOwner(currentOwner);
191	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Transactional
196	    @Override
197	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
198	        Owner owner = this.clinicService.findOwnerById(ownerId);
199	        if (owner == null) {
200	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
201	        }
202	        this.clinicService.deleteOwner(owner);
203	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
204	    }
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
209	        Owner owner = this.clinicService.findOwnerById(ownerId);
210	        if (owner == null) {
211	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	        }
213	        HttpHeaders headers = new HttpHeaders();
214	        Pet pet = petMapper.toPet(petFieldsDto);
215	        owner.setId(ownerId);
216	        pet.setOwner(owner);
217	        pet.getType().setName(null);
218	        this.clinicService.savePet(pet);
219	        PetDto petDto = petMapper.toPetDto(pet);
220	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
221	            .buildAndExpand(pet.getId()).toUri());
222	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
223	    }
224	
225	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
226	    @Override
227	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
228	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
229	        if (currentOwner != null) {
230	            Pet currentPet = this.clinicService.findPetById(petId);
231	            if (currentPet != null) {
232	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
233	                currentPet.setName(petFieldsDto.getName());
234	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
235	                this.clinicService.savePet(currentPet);
236	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
237	            }
238	        }
239	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	    }
241	
242	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
243	    @Override
244	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
245	        HttpHeaders headers = new HttpHeaders();
246	        Visit visit = visitMapper.toVisit(visitFieldsDto);
247	        Pet pet = new Pet();
248	        pet.setId(petId);
249	        visit.setPet(pet);
250	        this.clinicService.saveVisit(visit);
251	        VisitDto visitDto = visitMapper.toVisitDto(visit);
252	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
253	            .buildAndExpand(visit.getId()).toUri());
254	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
255	    }
256	
257	
258	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
259	    @Override
260	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
261	        Owner owner = this.clinicService.findOwnerById(ownerId);
262	        if (owner != null) {
263	            Pet pet = owner.getPet(petId);
264	            if (pet != null) {
265	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
266	            }
267	        }
268	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
269	    }
270	}
