        boolean uniquelyNamed = Integer.valueOf(0).equals(this.namesakeCount);
        if (uniquelyNamed) {
            level++;
        }
        boolean tenured = getTenureDays() > 365;
        if (tenured) {
            level++;
        }
        return Math.min(level, 4);
    }

